   is_featured, is_ai_generated, published_at)
values (
  'en-zodiac-elements-trivia',
  'Zodiac Elements Trivia: Triplicities, Modalities and Polarity',
  'Eight questions on the zodiac''s four elements: triplicities, the cardinal, fixed and mutable modalities, and the classical polarity of the twelve signs.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'lifestyle'),
  '[{"id":"q1","question":"Which three signs make up the zodiac''s earth triplicity?","options":[{"id":"a","text":"Aries, Leo and Sagittarius","is_correct":false},{"id":"b","text":"Taurus, Virgo and Capricorn","is_correct":true},{"id":"c","text":"Gemini, Libra and Aquarius","is_correct":false},{"id":"d","text":"Cancer, Scorpio and Pisces","is_correct":false}],"explanation":"Earth unites Taurus, Virgo and Capricorn; fire, air and water group the other nine signs in threes."},{"id":"q2","question":"Which modality groups Taurus, Leo, Scorpio and Aquarius?","options":[{"id":"a","text":"Cardinal","is_correct":false},{"id":"b","text":"Fixed","is_correct":true},{"id":"c","text":"Mutable","is_correct":false},{"id":"d","text":"Dual","is_correct":false}],"explanation":"The fixed signs fall in the middle of each season; tradition links them to steadiness and persistence."},{"id":"q3","question":"Gemini, Virgo, Sagittarius and Pisces share which modality?","options":[{"id":"a","text":"Cardinal","is_correct":false},{"id":"b","text":"Fixed","is_correct":false},{"id":"c","text":"Mutable","is_correct":true},{"id":"d","text":"Angular","is_correct":false}],"explanation":"Mutable signs close each season, and tradition associates them with adaptability and change."},{"id":"q4","question":"In the classical scheme, fire and air signs belong to which polarity?","options":[{"id":"a","text":"Masculine or active","is_correct":true},{"id":"b","text":"Feminine or passive","is_correct":false},{"id":"c","text":"Nocturnal","is_correct":false},{"id":"d","text":"Neutral","is_correct":false}],"explanation":"Traditional astrology divides the signs into two polarities: fire and air as masculine or active, earth and water as feminine or receptive."},{"id":"q5","question":"What is the technical term for a group of three signs sharing an element?","options":[{"id":"a","text":"Triplicity","is_correct":true},{"id":"b","text":"Quadruplicity","is_correct":false},{"id":"c","text":"Decan","is_correct":false},{"id":"d","text":"Cusp","is_correct":false}],"explanation":"Three signs per element form a triplicity; the four-sign groups of cardinal, fixed and mutable are called quadruplicities."},{"id":"q6","question":"Every sign combines one element with one modality. Which sign pairs fire with the fixed modality?","options":[{"id":"a","text":"Aries","is_correct":false},{"id":"b","text":"Leo","is_correct":true},{"id":"c","text":"Sagittarius","is_correct":false},{"id":"d","text":"Gemini","is_correct":false}],"explanation":"Aries is cardinal fire, Leo is fixed fire and Sagittarius is mutable fire: each element-modality pairing appears exactly once."},{"id":"q7","question":"The four-element scheme that astrology inherited is credited to which Greek thinker?","options":[{"id":"a","text":"Empedocles","is_correct":true},{"id":"b","text":"Pythagoras","is_correct":false},{"id":"c","text":"Aristotle","is_correct":false},{"id":"d","text":"Plato","is_correct":false}],"explanation":"Empedocles proposed the four ''roots'' — earth, water, air and fire — in the fifth century BC; Aristotle later added a fifth element, aether."},{"id":"q8","question":"Which water sign is also a cardinal sign?","options":[{"id":"a","text":"Cancer","is_correct":true},{"id":"b","text":"Scorpio","is_correct":false},{"id":"c","text":"Pisces","is_correct":false},{"id":"d","text":"Aquarius","is_correct":false}],"explanation":"Cancer is cardinal water, Scorpio fixed water and Pisces mutable water; Aquarius is an air sign despite its water-bearer symbol."}]'::jsonb,
  null,
  array['zodiac', 'astrology', 'elements', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
