insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-elementos-del-zodiaco',
  'Trivia de elementos del zodiaco: triplicidades y modalidades',
  'Ocho preguntas sobre los cuatro elementos del zodiaco: triplicidades, modalidades cardinales, fijas y mutables, y la polaridad clásica de los doce signos.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'lifestyle'),
  '[{"id":"q1","question":"¿Qué tres signos forman la triplicidad de tierra del zodiaco?","options":[{"id":"a","text":"Aries, Leo y Sagitario","is_correct":false},{"id":"b","text":"Tauro, Virgo y Capricornio","is_correct":true},{"id":"c","text":"Géminis, Libra y Acuario","is_correct":false},{"id":"d","text":"Cáncer, Escorpio y Piscis","is_correct":false}],"explanation":"La tierra une a Tauro, Virgo y Capricornio; el fuego, el aire y el agua agrupan a los otros nueve signos de tres en tres."},{"id":"q2","question":"¿Qué modalidad agrupa a Tauro, Leo, Escorpio y Acuario?","options":[{"id":"a","text":"Cardinal","is_correct":false},{"id":"b","text":"Fija","is_correct":true},{"id":"c","text":"Mutable","is_correct":false},{"id":"d","text":"Dual","is_correct":false}],"explanation":"Los signos fijos caen en plena estación; la tradición los asocia con la constancia y la persistencia."},{"id":"q3","question":"Géminis, Virgo, Sagitario y Piscis comparten ¿qué modalidad?","options":[{"id":"a","text":"Cardinal","is_correct":false},{"id":"b","text":"Fija","is_correct":false},{"id":"c","text":"Mutable","is_correct":true},{"id":"d","text":"Angular","is_correct":false}],"explanation":"Los signos mutables cierran cada estación, y la tradición los relaciona con la adaptabilidad y el cambio."},{"id":"q4","question":"En el esquema clásico, los signos de fuego y de aire pertenecen a ¿qué polaridad?","options":[{"id":"a","text":"Masculina o activa","is_correct":true},{"id":"b","text":"Femenina o pasiva","is_correct":false},{"id":"c","text":"Nocturna","is_correct":false},{"id":"d","text":"Neutral","is_correct":false}],"explanation":"La astrología tradicional divide los signos en dos polaridades: fuego y aire como masculinos o activos, tierra y agua como femeninos o receptivos."},{"id":"q5","question":"¿Cómo se llama técnicamente el grupo de tres signos que comparten un elemento?","options":[{"id":"a","text":"Triplicidad","is_correct":true},{"id":"b","text":"Cuadruplicidad","is_correct":false},{"id":"c","text":"Decanato","is_correct":false},{"id":"d","text":"Cúspide","is_correct":false}],"explanation":"Tres signos por elemento forman una triplicidad; los grupos de cuatro signos cardinales, fijos y mutables se llaman cuadruplicidades."},{"id":"q6","question":"Cada signo combina un elemento con una modalidad. ¿Qué signo junta el fuego con la modalidad fija?","options":[{"id":"a","text":"Aries","is_correct":false},{"id":"b","text":"Leo","is_correct":true},{"id":"c","text":"Sagitario","is_correct":false},{"id":"d","text":"Géminis","is_correct":false}],"explanation":"Aries es fuego cardinal, Leo es fuego fijo y Sagitario es fuego mutable: cada combinación de elemento y modalidad aparece una sola vez."},{"id":"q7","question":"¿A qué pensador griego se atribuye el esquema de cuatro elementos que heredó la astrología?","options":[{"id":"a","text":"Empédocles","is_correct":true},{"id":"b","text":"Pitágoras","is_correct":false},{"id":"c","text":"Aristóteles","is_correct":false},{"id":"d","text":"Platón","is_correct":false}],"explanation":"Empédocles propuso las cuatro «raíces» — tierra, agua, aire y fuego — en el siglo V a. C.; Aristóteles añadió después un quinto elemento, el éter."},{"id":"q8","question":"¿Qué signo de agua es además un signo cardinal?","options":[{"id":"a","text":"Cáncer","is_correct":true},{"id":"b","text":"Escorpio","is_correct":false},{"id":"c","text":"Piscis","is_correct":false},{"id":"d","text":"Acuario","is_correct":false}],"explanation":"Cáncer es agua cardinal, Escorpio agua fija y Piscis agua mutable; Acuario es un signo de aire pese a su símbolo del aguador."}]'::jsonb,
  null,
  array['zodiaco', 'astrología', 'elementos', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
