insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-astrology-history-trivia',
  'Astrology History Trivia: From Babylon to the Horoscope',
  'Eight questions on the origins of astrology: the Babylonian division of the ecliptic, the Greek legacy and the birth of the personal horoscope.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'lifestyle'),
  '[{"id":"q1","question":"The twelve-sign zodiac first took shape in which ancient civilization?","options":[{"id":"a","text":"Egypt","is_correct":false},{"id":"b","text":"Babylonia","is_correct":true},{"id":"c","text":"Greece","is_correct":false},{"id":"d","text":"Rome","is_correct":false}],"explanation":"Babylonian scholars in Mesopotamia divided the ecliptic into twelve equal signs; Egypt and Greece adopted the scheme later."},{"id":"q2","question":"Around which century did Babylonian scholars divide the ecliptic into twelve equal signs?","options":[{"id":"a","text":"15th century BC","is_correct":false},{"id":"b","text":"5th century BC","is_correct":true},{"id":"c","text":"1st century AD","is_correct":false},{"id":"d","text":"10th century AD","is_correct":false}],"explanation":"The twelve equal signs of thirty degrees each appear in Babylonian texts around the fifth century BC, building on older omen traditions."},{"id":"q3","question":"The Greek word at the root of ''zodiac'' means roughly what?","options":[{"id":"a","text":"Circle of little animals","is_correct":true},{"id":"b","text":"Wheel of the stars","is_correct":false},{"id":"c","text":"Path of the gods","is_correct":false},{"id":"d","text":"Ring of light","is_correct":false}],"explanation":"Zōidiakos kyklos means ''circle of little figures'' — most of them animals — which is why the word zodiac shares a root with zoo."},{"id":"q4","question":"Which second-century scholar wrote the Tetrabiblos, antiquity''s most influential astrology manual?","options":[{"id":"a","text":"Claudius Ptolemy","is_correct":true},{"id":"b","text":"Aristotle","is_correct":false},{"id":"c","text":"Hipparchus","is_correct":false},{"id":"d","text":"Galen","is_correct":false}],"explanation":"Ptolemy of Alexandria wrote the Tetrabiblos (''four books''), which organized astrological doctrine and stayed authoritative for over a thousand years."},{"id":"q5","question":"Astrology spread through the Greek-speaking world mainly during which era?","options":[{"id":"a","text":"The Bronze Age","is_correct":false},{"id":"b","text":"The Hellenistic period","is_correct":true},{"id":"c","text":"The Renaissance","is_correct":false},{"id":"d","text":"The Middle Ages","is_correct":false}],"explanation":"After Alexander''s conquests, Babylonian and Egyptian traditions merged with Greek learning in the Hellenistic period, from the late fourth century BC."},{"id":"q6","question":"Which Egyptian city became the great center of astrological learning in antiquity?","options":[{"id":"a","text":"Alexandria","is_correct":true},{"id":"b","text":"Thebes","is_correct":false},{"id":"c","text":"Memphis","is_correct":false},{"id":"d","text":"Heliopolis","is_correct":false}],"explanation":"Alexandria''s scholars, Ptolemy among them, fused Babylonian star lore with Greek mathematics and astronomy."},{"id":"q7","question":"The long Babylonian series of tablets recording celestial omens is known as what?","options":[{"id":"a","text":"Enūma Anu Enlil","is_correct":true},{"id":"b","text":"Epic of Gilgamesh","is_correct":false},{"id":"c","text":"Code of Hammurabi","is_correct":false},{"id":"d","text":"Emerald Tablet","is_correct":false}],"explanation":"Enūma Anu Enlil collected thousands of celestial omens on about seventy tablets; Gilgamesh is an epic and Hammurabi''s code is a law text."},{"id":"q8","question":"A traditional birth chart is cast from which three pieces of information?","options":[{"id":"a","text":"Date, time and place of birth","is_correct":true},{"id":"b","text":"Name and date of birth","is_correct":false},{"id":"c","text":"Place and name of birth","is_correct":false},{"id":"d","text":"Date of birth only","is_correct":false}],"explanation":"The chart maps the sky for an exact date, time and place; the hour matters because the rising sign changes roughly every two hours."}]'::jsonb,
  null,
  array['astrology', 'history', 'babylon', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-historia-de-la-astrologia',
  'Trivia de historia de la astrología: de Babilonia al horóscopo',
  'Ocho preguntas sobre los orígenes de la astrología: la división babilónica de la eclíptica, el legado griego y el nacimiento del horóscopo personal.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'lifestyle'),
  '[{"id":"q1","question":"¿En qué civilización antigua tomó forma el zodiaco de doce signos?","options":[{"id":"a","text":"Egipto","is_correct":false},{"id":"b","text":"Babilonia","is_correct":true},{"id":"c","text":"Grecia","is_correct":false},{"id":"d","text":"Roma","is_correct":false}],"explanation":"Los sabios babilonios de Mesopotamia dividieron la eclíptica en doce signos iguales; Egipto y Grecia adoptaron el esquema más tarde."},{"id":"q2","question":"¿Hacia qué siglo dividieron los babilonios la eclíptica en doce signos iguales?","options":[{"id":"a","text":"Siglo XV a. C.","is_correct":false},{"id":"b","text":"Siglo V a. C.","is_correct":true},{"id":"c","text":"Siglo I d. C.","is_correct":false},{"id":"d","text":"Siglo X d. C.","is_correct":false}],"explanation":"Los doce signos iguales de treinta grados aparecen en textos babilonios hacia el siglo V a. C., sobre tradiciones de presagios más antiguas."},{"id":"q3","question":"La palabra griega en la raíz de «zodiaco» significa aproximadamente…","options":[{"id":"a","text":"«círculo de animalitos»","is_correct":true},{"id":"b","text":"«rueda de las estrellas»","is_correct":false},{"id":"c","text":"«camino de los dioses»","is_correct":false},{"id":"d","text":"«anillo de luz»","is_correct":false}],"explanation":"Zōidiakos kyklos quiere decir «círculo de figuritas» — casi todas animales — y por eso zodiaco comparte raíz con zoológico."},{"id":"q4","question":"¿Qué sabio del siglo II escribió el Tetrabiblos, el manual astrológico más influyente de la Antigüedad?","options":[{"id":"a","text":"Claudio Ptolomeo","is_correct":true},{"id":"b","text":"Aristóteles","is_correct":false},{"id":"c","text":"Hiparco","is_correct":false},{"id":"d","text":"Galeno","is_correct":false}],"explanation":"Ptolomeo de Alejandría escribió el Tetrabiblos («cuatro libros»), que ordenó la doctrina astrológica y siguió siendo autoridad durante más de mil años."},{"id":"q5","question":"¿Durante qué época se difundió la astrología por el mundo de habla griega?","options":[{"id":"a","text":"La Edad del Bronce","is_correct":false},{"id":"b","text":"El período helenístico","is_correct":true},{"id":"c","text":"El Renacimiento","is_correct":false},{"id":"d","text":"La Edad Media","is_correct":false}],"explanation":"Tras las conquistas de Alejandro, las tradiciones babilónicas y egipcias se fundieron con el saber griego en el período helenístico, desde finales del siglo IV a. C."},{"id":"q6","question":"¿Qué ciudad egipcia se convirtió en el gran centro del saber astrológico de la Antigüedad?","options":[{"id":"a","text":"Alejandría","is_correct":true},{"id":"b","text":"Tebas","is_correct":false},{"id":"c","text":"Menfis","is_correct":false},{"id":"d","text":"Heliópolis","is_correct":false}],"explanation":"Los sabios de Alejandría, entre ellos Ptolomeo, fundieron el saber estelar babilónico con las matemáticas y la astronomía griegas."},{"id":"q7","question":"¿Cómo se llama la larga serie babilónica de tablillas con presagios celestes?","options":[{"id":"a","text":"Enūma Anu Enlil","is_correct":true},{"id":"b","text":"Epopeya de Gilgamesh","is_correct":false},{"id":"c","text":"Código de Hammurabi","is_correct":false},{"id":"d","text":"Tabla Esmeralda","is_correct":false}],"explanation":"Enūma Anu Enlil reunió miles de presagios celestes en unas setenta tablillas; Gilgamesh es una epopeya y el Código de Hammurabi es un texto de leyes."},{"id":"q8","question":"¿Con qué tres datos se levanta tradicionalmente una carta natal?","options":[{"id":"a","text":"Fecha, hora y lugar de nacimiento","is_correct":true},{"id":"b","text":"Nombre y fecha de nacimiento","is_correct":false},{"id":"c","text":"Lugar y nombre de nacimiento","is_correct":false},{"id":"d","text":"Solo la fecha de nacimiento","is_correct":false}],"explanation":"La carta dibuja el cielo para una fecha, hora y lugar exactos; la hora importa porque el signo ascendente cambia más o menos cada dos horas."}]'::jsonb,
  null,
  array['astrología', 'historia', 'babilonia', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
