insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-astrology-planets-trivia',
  'Astrology Planets Trivia: The Ruling Body of Each Sign',
  'Eight questions on astrology''s ruling bodies: the seven classical planets and the modern planets assigned to each zodiac sign.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'lifestyle'),
  '[{"id":"q1","question":"Which planet rules Aries in traditional astrology?","options":[{"id":"a","text":"Mars","is_correct":true},{"id":"b","text":"Venus","is_correct":false},{"id":"c","text":"Jupiter","is_correct":false},{"id":"d","text":"Mercury","is_correct":false}],"explanation":"Aries belongs to Mars in the classical scheme, a pairing medieval astrologers read as drive and initiative."},{"id":"q2","question":"Mercury is the traditional ruler of Gemini and which other sign?","options":[{"id":"a","text":"Virgo","is_correct":true},{"id":"b","text":"Libra","is_correct":false},{"id":"c","text":"Aquarius","is_correct":false},{"id":"d","text":"Pisces","is_correct":false}],"explanation":"Before the outer planets were known, each of the five classical planets ruled two signs; Mercury held Gemini and Virgo."},{"id":"q3","question":"Which sign does Jupiter traditionally rule?","options":[{"id":"a","text":"Sagittarius","is_correct":true},{"id":"b","text":"Capricorn","is_correct":false},{"id":"c","text":"Aquarius","is_correct":false},{"id":"d","text":"Leo","is_correct":false}],"explanation":"Jupiter rules Sagittarius in the classical scheme; it also held Pisces before Neptune was discovered."},{"id":"q4","question":"Saturn is the classical ruler of which sign?","options":[{"id":"a","text":"Capricorn","is_correct":true},{"id":"b","text":"Taurus","is_correct":false},{"id":"c","text":"Cancer","is_correct":false},{"id":"d","text":"Gemini","is_correct":false}],"explanation":"Saturn rules Capricorn, and traditionally Aquarius too; it was the slowest and outermost planet visible to the naked eye."},{"id":"q5","question":"In modern astrology, which planet is assigned as ruler of Scorpio?","options":[{"id":"a","text":"Pluto","is_correct":true},{"id":"b","text":"Mars","is_correct":false},{"id":"c","text":"Neptune","is_correct":false},{"id":"d","text":"Saturn","is_correct":false}],"explanation":"Scorpio kept Mars as its classical ruler, and modern astrologers added Pluto after its discovery in 1930."},{"id":"q6","question":"Which celestial body rules Cancer?","options":[{"id":"a","text":"The Moon","is_correct":true},{"id":"b","text":"Venus","is_correct":false},{"id":"c","text":"Mercury","is_correct":false},{"id":"d","text":"Neptune","is_correct":false}],"explanation":"Astrology counts the Sun and Moon among its ''planets''; Cancer belongs to the Moon and Leo to the Sun."},{"id":"q7","question":"Uranus is the modern ruler of which sign?","options":[{"id":"a","text":"Aquarius","is_correct":true},{"id":"b","text":"Capricorn","is_correct":false},{"id":"c","text":"Pisces","is_correct":false},{"id":"d","text":"Gemini","is_correct":false}],"explanation":"Aquarius kept Saturn as its classical ruler; Uranus, discovered in 1781, was added as its modern ruler."},{"id":"q8","question":"Neptune is the modern ruler of which sign?","options":[{"id":"a","text":"Pisces","is_correct":true},{"id":"b","text":"Scorpio","is_correct":false},{"id":"c","text":"Cancer","is_correct":false},{"id":"d","text":"Sagittarius","is_correct":false}],"explanation":"Pisces was traditionally ruled by Jupiter; Neptune, discovered in 1846, took over as the sign''s modern ruler."}]'::jsonb,
  null,
  array['astrology', 'planets', 'zodiac', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
