insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-planetas-y-astrologia',
  'Trivia de planetas y astrología: el astro regente de cada signo',
  'Ocho preguntas sobre los regentes de la tradición astrológica: los siete astros clásicos y los planetas modernos asignados a cada signo del zodiaco.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'lifestyle'),
  '[{"id":"q1","question":"¿Qué planeta rige a Aries en la astrología tradicional?","options":[{"id":"a","text":"Marte","is_correct":true},{"id":"b","text":"Venus","is_correct":false},{"id":"c","text":"Júpiter","is_correct":false},{"id":"d","text":"Mercurio","is_correct":false}],"explanation":"Aries pertenece a Marte en el esquema clásico, una pareja que los astrólogos medievales leían como ímpetu e iniciativa."},{"id":"q2","question":"Mercurio es el regente tradicional de Géminis y de ¿qué otro signo?","options":[{"id":"a","text":"Virgo","is_correct":true},{"id":"b","text":"Libra","is_correct":false},{"id":"c","text":"Acuario","is_correct":false},{"id":"d","text":"Piscis","is_correct":false}],"explanation":"Antes de conocerse los planetas externos, cada uno de los cinco planetas clásicos regía dos signos; Mercurio tenía a Géminis y a Virgo."},{"id":"q3","question":"¿Qué signo rige Júpiter en la tradición clásica?","options":[{"id":"a","text":"Sagitario","is_correct":true},{"id":"b","text":"Capricornio","is_correct":false},{"id":"c","text":"Acuario","is_correct":false},{"id":"d","text":"Leo","is_correct":false}],"explanation":"Júpiter rige a Sagitario en el esquema clásico; también tenía a Piscis antes de que se descubriera Neptuno."},{"id":"q4","question":"Saturno es el regente clásico de ¿qué signo?","options":[{"id":"a","text":"Capricornio","is_correct":true},{"id":"b","text":"Tauro","is_correct":false},{"id":"c","text":"Cáncer","is_correct":false},{"id":"d","text":"Géminis","is_correct":false}],"explanation":"Saturno rige a Capricornio, y tradicionalmente también a Acuario; era el planeta más lento y externo visible a simple vista."},{"id":"q5","question":"En la astrología moderna, ¿qué planeta se asigna como regente de Escorpio?","options":[{"id":"a","text":"Plutón","is_correct":true},{"id":"b","text":"Marte","is_correct":false},{"id":"c","text":"Neptuno","is_correct":false},{"id":"d","text":"Saturno","is_correct":false}],"explanation":"Escorpio conservó a Marte como regente clásico, y los astrólogos modernos le añadieron Plutón tras su descubrimiento en 1930."},{"id":"q6","question":"¿Qué astro rige a Cáncer?","options":[{"id":"a","text":"La Luna","is_correct":true},{"id":"b","text":"Venus","is_correct":false},{"id":"c","text":"Mercurio","is_correct":false},{"id":"d","text":"Neptuno","is_correct":false}],"explanation":"La astrología cuenta al Sol y a la Luna entre sus «planetas»; Cáncer pertenece a la Luna y Leo al Sol."},{"id":"q7","question":"Urano es el regente moderno de ¿qué signo?","options":[{"id":"a","text":"Acuario","is_correct":true},{"id":"b","text":"Capricornio","is_correct":false},{"id":"c","text":"Piscis","is_correct":false},{"id":"d","text":"Géminis","is_correct":false}],"explanation":"Acuario conservó a Saturno como regente clásico; Urano, descubierto en 1781, se añadió como su regente moderno."},{"id":"q8","question":"Neptuno es el regente moderno de ¿qué signo?","options":[{"id":"a","text":"Piscis","is_correct":true},{"id":"b","text":"Escorpio","is_correct":false},{"id":"c","text":"Cáncer","is_correct":false},{"id":"d","text":"Sagitario","is_correct":false}],"explanation":"Piscis era regido tradicionalmente por Júpiter; Neptuno, descubierto en 1846, pasó a ser su regente moderno."}]'::jsonb,
